"""matplotlib._layoutgrid — constrained-layout grid stub."""


class LayoutGrid:
    def __init__(self, parent=None, parent_pos=(0, 0), parent_inner=False,
                 name='', ncols=1, nrows=1, h_pad=None, w_pad=None,
                 width_ratios=None, height_ratios=None):
        self.parent = parent
        self.name = name
        self.ncols = ncols
        self.nrows = nrows
        self.children = {}

    def add_child(self, child, i=0, j=0): self.children[(i, j)] = child
    def parent_constrain(self): pass
    def add_constraints(self, solver): pass
    def get_inner_bbox(self, rows=None, cols=None): return None
    def get_outer_bbox(self, rows=None, cols=None): return None
    def get_left_margin_bbox(self, rows=None, cols=None): return None
    def get_right_margin_bbox(self, rows=None, cols=None): return None
    def get_bottom_margin_bbox(self, rows=None, cols=None): return None
    def get_top_margin_bbox(self, rows=None, cols=None): return None
    def edit_margin(self, *args, **kwargs): pass
    def edit_margin_min(self, *args, **kwargs): pass
    def edit_margins(self, **kwargs): pass
    def edit_all_margins_min(self, *args, **kwargs): pass
    def edit_outer_margin_mins(self, *args, **kwargs): pass


# ─── Added: missing public helpers from upstream _layoutgrid.py ─────


_seq_id_counter = 0


def seq_id():
    """Return a monotonically-increasing sequence id. Used by upstream's
    layout grid to give each cell a unique handle."""
    global _seq_id_counter
    _seq_id_counter += 1
    return _seq_id_counter


def plot_children(layout, level=0):
    """Debug helper that visualises a layout grid by recursing through
    its children. No-op in the shim — we return an empty list so
    callers (typically logging/tests) don't crash."""
    return []
